CREATE TABLE `service` (
  `service_id` int(11) NOT NULL,
  `booking_id` int(11) DEFAULT NULL,
  `service_type` varchar(100) DEFAULT NULL,
  `fee` decimal(10,2) DEFAULT NULL,
  `staff_id` int(11) DEFAULT NULL,
  `status` enum('pending','out_for_delivery','delivered') DEFAULT 'pending',
  `pickup_status` enum('pending','out_for_delivery','delivered') NOT NULL DEFAULT 'pending',
  `pickup_status_at` datetime DEFAULT NULL,
  `return_status` enum('pending','out_for_delivery','delivered') DEFAULT NULL,
