--
-- Triggers `service`
--
DELIMITER $$
CREATE TRIGGER `trg_service_after_delete` AFTER DELETE ON `service` FOR EACH ROW BEGIN
  IF OLD.service_type IN ('delivery','pickup_and_return') THEN
    /* Find another delivery row (should not exist if enforcing uniqueness) */
    UPDATE booking b
    LEFT JOIN (
      SELECT s.booking_id, s.fee
      FROM service s
      WHERE s.booking_id = OLD.booking_id
        AND s.service_type IN ('delivery','pickup_and_return')
      ORDER BY s.service_id DESC
      LIMIT 1
    ) x ON x.booking_id = b.booking_id
    SET b.total_price =
        (b.day_count * b.daily_rate) + b.security_deposit + IFNULL(x.fee,0)
    WHERE b.booking_id = OLD.booking_id;
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_service_after_insert` AFTER INSERT ON `service` FOR EACH ROW BEGIN
  IF NEW.service_type IN ('delivery','pickup_and_return') THEN
    UPDATE booking b
      SET b.total_price =
          (b.day_count * b.daily_rate) + b.security_deposit + IFNULL(NEW.fee,0)
      WHERE b.booking_id = NEW.booking_id;
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_service_after_update` AFTER UPDATE ON `service` FOR EACH ROW BEGIN
  /* Use NEW (not OLD) values */
  IF NEW.service_type IN ('delivery','pickup_and_return')
     OR OLD.service_type IN ('delivery','pickup_and_return') THEN
    /* We recalc using NEW if the row is still delivery-related; if it changed away
       from delivery types, we must look for any remaining delivery row. */
    IF NEW.service_type IN ('delivery','pickup_and_return') THEN
      UPDATE booking b
        SET b.total_price =
            (b.day_count * b.daily_rate) + b.security_deposit + IFNULL(NEW.fee,0)
        WHERE b.booking_id = NEW.booking_id;
    ELSE
      /* Row changed from a delivery type to a non-delivery type:
         look for another existing delivery row (if any); else base total */
      UPDATE booking b
      LEFT JOIN (
        SELECT s.booking_id, s.fee
        FROM service s
        WHERE s.booking_id = OLD.booking_id
          AND s.service_type IN ('delivery','pickup_and_return')
        ORDER BY s.service_id DESC
        LIMIT 1
      ) x ON x.booking_id = b.booking_id
      SET b.total_price =
          (b.day_count * b.daily_rate) + b.security_deposit + IFNULL(x.fee,0)
      WHERE b.booking_id = OLD.booking_id;
    END IF;
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_service_status_change` BEFORE UPDATE ON `service` FOR EACH ROW BEGIN
  IF NEW.status <> OLD.status
     AND NEW.status = 'out_for_delivery' THEN
     SET NEW.notified = 0;
  END IF;
END
$$
DELIMITER ;

